import { FileTextIcon, SparklesIcon } from "@/components/icons";
import type { ActivityItem } from "@/types";

export function ActivityRow({ item }: { item: ActivityItem; index: number }) {
  const isPlan = item.label.toLowerCase().includes("plan");
  return (
    <div className="activity-row">
      <div className="activity-icon">
        {isPlan ? <SparklesIcon size={16} /> : <FileTextIcon size={16} />}
      </div>
      <div style={{ minWidth: 0, flex: 1 }}>
        <p className="activity-label">{item.label}</p>
        <p className="activity-detail">{item.detail}</p>
      </div>
      <span className="activity-time">{item.timestamp}</span>
    </div>
  );
}
